to resolve this deterministically without burning extra round-trips or tokens, your agent loop must catch the plain tool_use shape for MCP tools, seamlessly resolve it client-side by talking directly to your MCP server structure, and return a clean tool_result to keep the model moving down the correct path.

Below is the production-ready drop-in replacement logic for your streaming execution block.

Python
import anthropic

# Assuming these variables are already initialized in your framework:
# anthropic_client = anthropic.Anthropic()
# server_managed_tool_names = {"<tool_a>", "<tool_b>"}
# mcp_server_client = your_mcp_client_instance_or_handler

def execute_agent_turn(request_payload):
    # Initialize state variables to track streaming tools
    current_tool_id = None
    current_tool_name = None
    current_tool_input_str = ""
    is_mcp_style = False

    # 1. Fire the stream
    stream = anthropic_client.beta.messages.stream(**request_payload)

    for event in stream:
        # Detect block starts
        if event.type == "content_block_start":
            block_type = event.content_block.type
            if block_type == "mcp_tool_use":
                is_mcp_style = True  # Server-side handled perfectly
            elif block_type == "tool_use":
                is_mcp_style = False # Could be a local tool or the routing fallback bug
                current_tool_id = event.content_block.id
                current_tool_name = event.content_block.name
                current_tool_input_str = ""

        # Aggregate input arguments safely if it's a plain tool use text delta
        elif event.type == "content_block_delta":
            if not is_mcp_style and event.delta.type == "input_json_delta":
                current_tool_input_str += event.delta.partial_json

        # Handle completion of the content block
        elif event.type == "content_block_stop":
            # Check if a plain tool_use fell back onto an MCP-controlled tool name
            if not is_mcp_style and current_tool_name in server_managed_tool_names:
                import json
                try:
                    tool_args = json.loads(current_tool_input_str) if current_tool_input_str else {}
                except json.JSONDecodeError:
                    tool_args = {}

                # --- AUTO-HANDOFF INLINE EXECUTOR ---
                # Instead of sending a fake "OK", execute it client-side to keep context accurate
                try:
                    # Replace this invocation with your actual inner client execution logic
                    execution_result = mcp_server_client.call_tool(current_tool_name, tool_args)
                    result_text = json.dumps(execution_result.content)
                    is_error = getattr(execution_result, "is_error", False)
                except Exception as e:
                    result_text = f"Error executing fallback MCP tool client-side: {str(e)}"
                    is_error = True

                # Construct the matching client-side tool_result block
                fallback_tool_result_message = {
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": current_tool_id,
                            "content": result_text,
                            "is_error": is_error
                        }
                    ]
                }

                # Append both the faulted tool call and its fresh result directly to history
                request_payload["messages"].append({
                    "role": "assistant",
                    "content": [{
                        "type": "tool_use",
                        "id": current_tool_id,
                        "name": current_tool_name,
                        "input": tool_args
                    }]
                })
                request_payload["messages"].append(fallback_tool_result_message)

                # Close out the stream and recurse into the next turn immediately 
                stream.close()
                return execute_agent_turn(request_payload)

    # Normal non-fault handling for successful stream termination
    final_message = stream.get_final_message()
    request_payload["messages"].append({"role": "assistant", "content": final_message.content})
    return final_message
3. Recommended Payload Tweaks (Mitigation)
While utilizing the runner wrapper logic above will fix the hanging issue, you can substantially decrease the bug's frequency by altering your setup properties:

Relax the Effort Limit: If context compaction (clear_tool_uses) is heavily running, bump your parameters to "thinking": {"type": "adaptive"} and "effort": "medium" or "high". Low reasoning effort combined with heavy text modification increases structural drift.

Decouple Context Management Exclusions: Update your request configuration schema to instruct the context manager not to wipe historical tool calls belonging to your critical MCP definitions:

